import{_ as t,c as o,o as a,ag as i}from"./chunks/framework.DuVOYUUM.js";const g=JSON.parse('{"title":"Git Workflow & Contributing Guidelines","description":"","frontmatter":{},"headers":[],"relativePath":"software/contributing/git-workflow.md","filePath":"software/contributing/git-workflow.md","lastUpdated":1790647345000}'),r={name:"software/contributing/git-workflow.md"};function s(n,e,l,u,c,d){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="git-workflow-contributing-guidelines" tabindex="-1">Git Workflow &amp; Contributing Guidelines <a class="header-anchor" href="#git-workflow-contributing-guidelines" aria-label="Permalink to &quot;Git Workflow &amp; Contributing Guidelines&quot;">​</a></h1><p>Welcome to the team! To keep our codebase clean, organized, and maintainable, we follow a standardized Git workflow and contribution process.</p><h2 id="_0-helpful-links-to-resources-optional" tabindex="-1">0. Helpful Links to Resources (Optional) <a class="header-anchor" href="#_0-helpful-links-to-resources-optional" aria-label="Permalink to &quot;0. Helpful Links to Resources (Optional)&quot;">​</a></h2><ul><li>We use Git as our version control system. You can interact with Git through either the <a href="https://www.w3schools.com/git/" target="_blank" rel="noreferrer">CLI</a> or a <a href="https://code.visualstudio.com/docs/sourcecontrol/quickstart" target="_blank" rel="noreferrer">GUI</a>.</li><li>Our codebase is hosted on GitHub. You can browse the repository and contribute changes through <a href="https://docs.github.com/en/pull-requests/reference/pull-requests" target="_blank" rel="noreferrer">pull requests</a>.</li></ul><h2 id="_1-quick-overview-of-workflow-steps" tabindex="-1">1. Quick Overview of Workflow Steps <a class="header-anchor" href="#_1-quick-overview-of-workflow-steps" aria-label="Permalink to &quot;1. Quick Overview of Workflow Steps&quot;">​</a></h2><ol><li><strong>Find or Create an Issue:</strong> Express interest or define a task.</li><li><strong>Create a Feature Branch:</strong> Branch directly off <code>main</code> in the primary repository.</li><li><strong>Make Changes &amp; Commit:</strong> Follow our structured commit message guidelines.</li><li><strong>Push Branch &amp; Open a Pull Request (PR):</strong> Link the issue and fill out the PR template.</li><li><strong>Code Review &amp; Merge:</strong> Address feedback, obtain approval, and merge.</li></ol><h2 id="_2-issue-management-task-delegation" tabindex="-1">2. Issue Management &amp; Task Delegation <a class="header-anchor" href="#_2-issue-management-task-delegation" aria-label="Permalink to &quot;2. Issue Management &amp; Task Delegation&quot;">​</a></h2><p>Before starting any work, ensure an issue exists for the task.</p><h3 id="creating-an-issue" tabindex="-1">Creating an Issue <a class="header-anchor" href="#creating-an-issue" aria-label="Permalink to &quot;Creating an Issue&quot;">​</a></h3><ul><li><strong>Title:</strong> Clear, concise summary of the task, bug, or feature request.</li><li><strong>Description:</strong> Include background information, requirements, steps to reproduce (for bugs), and expected behavior or completion criteria.</li></ul><h3 id="task-delegation-claiming-issues" tabindex="-1">Task Delegation &amp; Claiming Issues <a class="header-anchor" href="#task-delegation-claiming-issues" aria-label="Permalink to &quot;Task Delegation &amp; Claiming Issues&quot;">​</a></h3><ul><li>We encourage members to claim issues that they are interested in and would like to work on. This gives you the freedom to explore areas of the project that interest you and develop skills you want to learn. If you&#39;re unsure what to work on or would like some direction, feel free to reach out to leadership and we can help find an appropriate issue or assignment.</li><li>If you would like to work on an issue, <a href="https://docs.github.com/en/issues/tracking-your-work-with-issues/using-issues/assigning-issues-and-pull-requests-to-other-github-users" target="_blank" rel="noreferrer">assign yourself</a> to the issue on GitHub. You may also comment on the issue to give additional information if needed.</li><li>This signals your interest to the rest of the team and prevents duplicate work.</li><li>Collaboration is welcome! If you&#39;d like to help out on an issue that&#39;s already assigned, reach out to the current assignee first so you can coordinate and work together.</li></ul><h2 id="_3-branching-guidelines" tabindex="-1">3. Branching Guidelines <a class="header-anchor" href="#_3-branching-guidelines" aria-label="Permalink to &quot;3. Branching Guidelines&quot;">​</a></h2><p><em>Note: We use a <strong>branching workflow</strong> directly within the primary repository (no forking required).</em></p><h3 id="branch-setup" tabindex="-1">Branch Setup <a class="header-anchor" href="#branch-setup" aria-label="Permalink to &quot;Branch Setup&quot;">​</a></h3><p>Create your branch directly off the latest <code>main</code> branch.</p><h3 id="naming-conventions" tabindex="-1">Naming Conventions <a class="header-anchor" href="#naming-conventions" aria-label="Permalink to &quot;Naming Conventions&quot;">​</a></h3><p>Branch names must be descriptive, lowercase, hyphen-separated, and clearly indicate the scope of work:</p><ul><li><strong>Features / Integrations:</strong> <code>zed-camera-integration</code>, <code>nav-behavior-tree</code></li><li><strong>Documentation:</strong> <code>update-git-docs</code>, <code>readme-setup-guide</code></li><li><strong>Configuration:</strong> <code>update-nav-config</code>, <code>ros2-control-params</code></li><li><strong>Bug Fixes:</strong> <code>fix-odom-tf-leak</code>, <code>fix-lidar-launch</code></li></ul><blockquote><p><strong>Rule:</strong> Keep branches focused on a single topic. Do not mix unrelated changes (e.g., navigation tweaks and documentation updates) in the same branch.</p></blockquote><h2 id="_4-commit-message-formatting" tabindex="-1">4. Commit Message Formatting <a class="header-anchor" href="#_4-commit-message-formatting" aria-label="Permalink to &quot;4. Commit Message Formatting&quot;">​</a></h2><ul><li><p><strong>Commit Message Format:</strong> Write clear, imperative commit messages (e.g., &quot;Add user authentication&quot; instead of &quot;Added user authentication&quot; or &quot;Adding user authentication&quot;). Think of the message as a command completing the sentence: &quot;If applied, this commit will...&quot;.</p></li><li><p><strong>Commit Principal:</strong> Commit early and commit often. Make small, logical commits as you work to keep your history clean, easier to review, and simple to revert if necessary.</p></li><li><p>For furthur guidance, follow the <a href="https://docs.ros.org/en/jazzy/The-ROS2-Project/Contributing/Developer-Guide.html#implementation" target="_blank" rel="noreferrer">ROS 2 contribution guidelines</a>.</p></li></ul><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><ul><li><code>Add missing transform link between map and odom.</code></li><li><code>Remove depricated package.xml dependancy entries.</code></li></ul><h2 id="_5-pull-requests-prs-code-reviews" tabindex="-1">5. Pull Requests (PRs) &amp; Code Reviews <a class="header-anchor" href="#_5-pull-requests-prs-code-reviews" aria-label="Permalink to &quot;5. Pull Requests (PRs) &amp; Code Reviews&quot;">​</a></h2><h3 id="creating-a-pull-request" tabindex="-1">Creating a Pull Request <a class="header-anchor" href="#creating-a-pull-request" aria-label="Permalink to &quot;Creating a Pull Request&quot;">​</a></h3><ol><li>Push your local branch to the central repository.</li><li>Open a Pull Request targeting the <code>main</code> branch.</li><li><strong>PR Title:</strong> Keep it aligned with commit style, brief and imperative (e.g., <code>Integrate ZED camera package</code>).</li><li><strong>Linking Issues:</strong> You <strong>must link the issue</strong> your PR addresses using GitHub&#39;s keyword auto-linking in the PR description: <ul><li>Use keywords such as <code>Closes #&lt;issue_number&gt;</code>, <code>Fixes #&lt;issue_number&gt;</code>, or <code>Resolves #&lt;issue_number&gt;</code> (e.g., <code>Closes #42</code>).</li><li>Linking the issue automatically closes it once the PR is merged into <code>main</code>.</li></ul></li></ol><h3 id="code-review-requirements" tabindex="-1">Code Review Requirements <a class="header-anchor" href="#code-review-requirements" aria-label="Permalink to &quot;Code Review Requirements&quot;">​</a></h3><ul><li>All PRs require <strong>at least one code review and approval</strong> from a reviewer prior to merging.</li><li>Reviewers will test, evaluate code quality, and ensure project guidelines are met.</li><li>If changes are requested, commit the updates to your existing branch and push; the PR will update automatically.</li><li>Once approved, the reviewer or author will merge the branch into <code>main</code> and delete the feature branch.</li></ul>',29)]))}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
